  try {
    if (window.mobileApp && typeof window.mobileApp.postMessage === 'function') window.mobileApp.postMessage({ detail: msg });
  } catch { /* bridge gone */ }
  try { if (typeof window.__apTestSink === 'function') window.__apTestSink(msg); } catch { /* test hook */ }
